/**
 * OMarkdownRenderer.impl - 实际 markdown 渲染实现。
 *
 * 注意:接手时需要装 react-markdown / remark-gfm / rehype-pretty-code / rehype-katex / remark-math
 * (在 package.json 中已声明)。如果项目不需要 math,可以删除 remark-math/rehype-katex。
 */
'use client';

import { useEffect, useState } from 'react';

interface ImplProps {
  content: string;
  gfm: boolean;
  highlight: boolean;
  math: boolean;
  allowHtml: boolean;
  codeTheme: string;
}

export function MarkdownImpl({
  content,
  gfm,
  highlight,
  math,
  allowHtml,
  codeTheme,
}: ImplProps) {
  const [Comp, setComp] = useState<React.ComponentType<{
    children: string;
    remarkPlugins?: unknown[];
    rehypePlugins?: unknown[];
    skipHtml?: boolean;
  }> | null>(null);
  const [plugins, setPlugins] = useState<{ remark: unknown[]; rehype: unknown[] } | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const [
        { default: ReactMarkdown },
        ...maybe
      ] = await Promise.all([
        import('react-markdown'),
        gfm ? import('remark-gfm') : Promise.resolve({ default: null }),
        math ? import('remark-math') : Promise.resolve({ default: null }),
        math ? import('rehype-katex') : Promise.resolve({ default: null }),
        highlight ? import('rehype-pretty-code' as never).catch(() => ({ default: null })) : Promise.resolve({ default: null }),
      ]);

      const remarkPlugins: unknown[] = [];
      const rehypePlugins: unknown[] = [];
      if (maybe[0]?.default) remarkPlugins.push(maybe[0].default);
      if (maybe[1]?.default) remarkPlugins.push(maybe[1].default);
      if (maybe[2]?.default) rehypePlugins.push(maybe[2].default);
      if (maybe[3]?.default) rehypePlugins.push([maybe[3].default, { theme: codeTheme }]);

      if (!cancelled) {
        setComp(() => ReactMarkdown as never);
        setPlugins({ remark: remarkPlugins, rehype: rehypePlugins });
      }
    })().catch((err) => console.error('[OMarkdownRenderer] load failed:', err));
    return () => {
      cancelled = true;
    };
  }, [gfm, math, highlight, codeTheme]);

  if (!Comp || !plugins) {
    return (
      <pre className="text-sm text-muted-foreground whitespace-pre-wrap font-sans @container">
        {content}
      </pre>
    );
  }

  return (
    <Comp remarkPlugins={plugins.remark} rehypePlugins={plugins.rehype} skipHtml={!allowHtml}>
      {content}
    </Comp>
  );
}
